<script lang="ts">
  import { session } from '../auth/session';
  let { userId }:{userId:string}=$props();let enabled=$state(false);let maximumAge=$state(12);let allowUnrated=$state(false);let error=$state('');let busy=$state(false);let loaded=$state(false);
  $effect(()=>{const id=userId;const controller=new AbortController();loaded=false;error='';fetch(`/api/v1/admin/users/${id}/parental`,{signal:controller.signal}).then(async response=>{if(!response.ok)throw new Error('Restrictions indisponibles.');return response.json();}).then(value=>{if(!controller.signal.aborted){enabled=value!==null;maximumAge=value?.maximumAge??12;allowUnrated=value?.allowUnrated??false;loaded=true;}}).catch(cause=>{if(!controller.signal.aborted)error=cause.message;});return()=>controller.abort();});
  async function save(event:SubmitEvent){event.preventDefault();busy=true;error='';try{const response=await fetch(`/api/v1/admin/users/${userId}/parental`,{method:enabled?'PUT':'DELETE',headers:{'content-type':'application/json','x-csrf-token':$session?.csrfToken??''},body:enabled?JSON.stringify({maximumAge,allowUnrated}):undefined});if(!response.ok)throw new Error('Restrictions non enregistrées.');}catch(cause){error=cause instanceof Error?cause.message:'Erreur';}finally{busy=false;}}
</script>
<form onsubmit={save}><fieldset disabled={busy||!loaded}><legend>Restrictions parentales</legend><label><input type="checkbox" bind:checked={enabled} />Limiter ce compte</label>{#if enabled}<label>Âge maximal autorisé<input type="number" min="0" max="21" required bind:value={maximumAge} /></label><label><input type="checkbox" bind:checked={allowUnrated} />Autoriser les médias sans classification connue</label><p>Les âges minimum peuvent être corrigés dans les fiches des médias. Les médias non classifiés sont bloqués par défaut.</p>{/if}<button>Enregistrer les restrictions</button></fieldset>{#if error}<p role="alert">{error}</p>{/if}</form>
<style>fieldset { display:grid;gap:12px;border:1px solid var(--color-line);border-radius:8px;margin:20px 0;padding:16px; } label { display:flex;gap:8px;align-items:center; } button,input[type=number] { background:var(--color-surface);color:var(--color-text);padding:10px;border:1px solid var(--color-line);border-radius:6px; } </style>
